/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field ReceiptDateRequested.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeSalesLineReceiptDateRequested extends UPSPricingAttributeSalesLine implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesLine, ReceiptDateRequested);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Date);
    SalesLine   salesLine;

    while select salesLine
        group by ReceiptDateRequested
    {
        if (! ret.in(salesLine.ReceiptDateRequested))
        {
            ret.add(salesLine.ReceiptDateRequested);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesLine, ReceiptDateRequested));
    qbr.value(queryValue(_value));
}
